 IF org IS NULL OR org='00000000-0000-0000-0000-000000000000' OR actor IS NULL OR actor !~ '^[A-Za-z0-9][A-Za-z0-9_-]{0,127}$'
  OR identity IS NULL OR identity='00000000-0000-0000-0000-000000000000' OR original_operation IS NULL
  OR original_operation='00000000-0000-0000-0000-000000000000' THEN RETURN NULL; END IF;
 IF NOT EXISTS(SELECT 1 FROM issuance_service.external_observation_lock_organization(org) WHERE status='active') THEN RETURN NULL; END IF;
 SELECT * INTO history FROM issuance_service.external_association_operations WHERE operation_id=original_operation;
 IF NOT FOUND OR history.organization_id<>org OR history.actor_type<>'user' OR history.actor_id<>actor
  OR history.resource_id<>identity OR history.action<>'association.unlink' THEN RETURN NULL; END IF;
 RETURN jsonb_build_object('kind','receipt','receipt',history.receipt);
END;

DECLARE before_row issuance_service.external_association_identities; wanted issuance_service.external_association_identities;
 saved issuance_service.external_association_identities; actual issuance_service.external_association_identities;
 history issuance_service.external_association_operations; expected_history issuance_service.external_association_operations;
 intent jsonb; answer jsonb; stamp timestamptz; edge issuance_service.external_association_bindings;
 expected_edge issuance_service.external_association_bindings; saved_edge issuance_service.external_association_bindings;
 expected_edges jsonb:='[]'::jsonb; actual_edges jsonb;
BEGIN
 IF org IS NULL OR org='00000000-0000-0000-0000-000000000000' OR actor IS NULL OR actor !~ '^[A-Za-z0-9][A-Za-z0-9_-]{0,127}$'
  OR op IS NULL OR op='00000000-0000-0000-0000-000000000000' OR identity IS NULL OR identity='00000000-0000-0000-0000-000000000000'
  OR expected_revision IS NULL OR expected_revision NOT BETWEEN 1 AND 9007199254740990 THEN RETURN NULL; END IF;
 IF NOT EXISTS(SELECT 1 FROM issuance_service.external_observation_lock_organization(org) WHERE status='active') THEN RETURN NULL; END IF;
 intent:=jsonb_build_object('expected_revision',expected_revision);
 PERFORM pg_advisory_xact_lock(hashtextextended('external-association-operation:'||op::text,0));
 SELECT * INTO history FROM issuance_service.external_association_operations WHERE operation_id=op;
 IF FOUND THEN
  IF history.organization_id=org AND history.actor_type='user' AND history.actor_id=actor AND history.resource_id=identity
   AND history.action='association.unlink' AND history.intent=intent THEN RETURN history.receipt; END IF;
  RETURN NULL;
 END IF;
 SELECT * INTO before_row FROM issuance_service.external_association_identities
  WHERE id=identity AND organization_id=org AND user_id=actor FOR UPDATE;
 IF NOT FOUND OR NOT before_row.active OR before_row.revision<>expected_revision THEN RETURN NULL; END IF;
 stamp:=clock_timestamp();wanted:=before_row;wanted.active:=false;wanted.consent_generation:=before_row.consent_generation+1;wanted.revision:=expected_revision+1;wanted.updated_at:=stamp;
 -- Freeze every existing edge. Relinking one new challenge must never revive
 -- earlier bindings merely because the global identity becomes active again.
 FOR edge IN SELECT * FROM issuance_service.external_association_bindings
  WHERE identity_id=identity ORDER BY binding_id FOR UPDATE LOOP
  expected_edge:=edge;
  IF edge.active THEN
   expected_edge.active:=false;expected_edge.revision:=edge.revision+1;expected_edge.updated_at:=stamp;
   UPDATE issuance_service.external_association_bindings SET active=false,revision=expected_edge.revision,updated_at=stamp
    WHERE identity_id=identity AND binding_id=edge.binding_id RETURNING * INTO saved_edge;
   IF to_jsonb(saved_edge) IS DISTINCT FROM to_jsonb(expected_edge) THEN
    RAISE EXCEPTION 'Association unlink binding changed' USING ERRCODE='23514'; END IF;
  END IF;
  expected_edges:=expected_edges||jsonb_build_array(to_jsonb(expected_edge));
 END LOOP;
 UPDATE issuance_service.external_association_identities SET active=false,consent_generation=wanted.consent_generation,revision=wanted.revision,updated_at=stamp
  WHERE id=identity RETURNING * INTO saved;
 IF to_jsonb(saved) IS DISTINCT FROM to_jsonb(wanted) THEN
  RAISE EXCEPTION 'Association unlink postimage changed' USING ERRCODE='23514'; END IF;
 answer:=jsonb_build_object('operation_id',op,'identity_id',identity,'action','unlink','revision',saved.revision,'active',false);
 expected_history:=jsonb_populate_record(NULL::issuance_service.external_association_operations,jsonb_build_object(
  'operation_id',op,'organization_id',org,'actor_type','user','actor_id',actor,'resource_id',identity,
  'action','association.unlink','intent',intent,'receipt',answer,'created_at',stamp));
 INSERT INTO issuance_service.external_association_operations SELECT expected_history.*;
 SELECT * INTO actual FROM issuance_service.external_association_identities WHERE id=identity;
 SELECT * INTO history FROM issuance_service.external_association_operations WHERE operation_id=op;
 SELECT COALESCE(jsonb_agg(to_jsonb(e) ORDER BY e.binding_id),'[]'::jsonb) INTO actual_edges
  FROM issuance_service.external_association_bindings e WHERE e.identity_id=identity;
 IF to_jsonb(actual) IS DISTINCT FROM to_jsonb(saved) OR to_jsonb(history) IS DISTINCT FROM to_jsonb(expected_history)
  OR actual_edges IS DISTINCT FROM expected_edges
  OR NOT EXISTS(SELECT 1 FROM issuance_service.external_observation_lock_organization(org) WHERE status='active') THEN
  RAISE EXCEPTION 'Association unlink authority or audit changed' USING ERRCODE='23514'; END IF;
 RETURN answer;
END;
